-- Local candidate: allow only positively verified REVOKE in REVIEW to close its
-- notice. No activation row is inserted and runtime remains opt-in.
CREATE TABLE IF NOT EXISTS continuous_revoke_review_close_activation(singleton INTEGER PRIMARY KEY CHECK(singleton=1),activated_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS continuous_revoke_review_close_activation_no_update BEFORE UPDATE ON continuous_revoke_review_close_activation BEGIN SELECT RAISE(ABORT,'review close activation immutable'); END;
CREATE TRIGGER IF NOT EXISTS continuous_revoke_review_close_activation_no_delete BEFORE DELETE ON continuous_revoke_review_close_activation BEGIN SELECT RAISE(ABORT,'review close activation retained'); END;
CREATE TRIGGER IF NOT EXISTS continuous_revoke_review_close_activation_no_replace BEFORE INSERT ON continuous_revoke_review_close_activation WHEN EXISTS(SELECT 1 FROM continuous_revoke_review_close_activation WHERE singleton=NEW.singleton OR rowid=NEW.rowid) BEGIN SELECT RAISE(ABORT,'review close activation collision'); END;
DROP TRIGGER IF EXISTS continuous_review_close_insert;
CREATE TRIGGER IF NOT EXISTS continuous_review_close_insert BEFORE INSERT ON continuous_review_notice_close
WHEN NEW.state<>'TIME_IN_FLIGHT' OR NEW.source_revision IS NOT NULL OR NOT EXISTS(
 SELECT 1 FROM stable_workbook_claims c
 JOIN stable_recovery_epochs e ON e.epoch_id=NEW.epoch_id AND e.spreadsheet_id=c.spreadsheet_id AND e.state='ARMED' AND e.target_type='EXPENSE' AND e.target_key=NEW.expense_id AND e.target_version=NEW.source_version
 JOIN stable_recovery_operations o ON o.epoch_id=e.epoch_id AND o.operation_token=c.operation_token AND o.state='ADMITTED'
 JOIN sync_jobs j ON j.entity_type='EXPENSE' AND j.entity_key=e.target_key AND j.entity_version=e.target_version AND ((NEW.claim_mode='REVIEW' AND j.status='REVIEW' AND (j.lease_token IS NULL AND j.lease_until IS NULL OR j.lease_until<=strftime('%Y-%m-%dT%H:%M:%fZ','now'))) OR (NEW.claim_mode='HANDOFF' AND j.status='PENDING' AND j.lease_token IS NULL AND j.lease_until IS NULL))
 WHERE c.spreadsheet_id=NEW.spreadsheet_id AND c.operation_token=NEW.operation_token AND ((NEW.claim_mode='REVIEW' AND c.state='REVIEW' AND c.phase='OPERATION') OR (NEW.claim_mode='HANDOFF' AND c.state='HELD' AND c.phase='END_NOTICE_PENDING' AND EXISTS(SELECT 1 FROM continuous_normal_notice_handoffs h WHERE h.spreadsheet_id=c.spreadsheet_id AND h.operation_token=c.operation_token AND h.expense_id=NEW.expense_id AND h.source_version=NEW.source_version AND h.projection=NEW.projection AND h.journal_entity=NEW.journal_entity AND h.operation_kind=NEW.operation_kind))) AND c.notice_identity=NEW.notice_identity AND c.notice_stamp=NEW.paused_stamp
 ) OR EXISTS(SELECT 1 FROM failed_jobs f WHERE f.queue_name='malipang-jobs' AND f.job_key='EXPENSE:'||NEW.expense_id||':'||NEW.source_version AND f.status='OPEN' AND f.error='DEAD_LETTER_MAX_RETRIES')
 OR (NEW.projection NOT IN ('FINAL','PUBLICATION') AND NEW.operation_kind='CONFIRM' AND NOT EXISTS(SELECT 1 FROM stable_projection_writes p WHERE p.spreadsheet_id=NEW.spreadsheet_id AND p.entity_type='EXPENSE' AND p.entity_id=NEW.journal_entity AND p.projection=NEW.projection AND p.source_version=NEW.source_version AND p.operation_token=NEW.operation_token AND p.state='VERIFIED'))
 OR (NEW.projection NOT IN ('FINAL','PUBLICATION') AND NEW.operation_kind='CANCEL' AND NOT EXISTS(SELECT 1 FROM stable_expense_cancellation_writes p WHERE p.spreadsheet_id=NEW.spreadsheet_id AND p.entity_type='EXPENSE' AND p.entity_id=NEW.journal_entity AND p.projection=NEW.projection AND p.cancellation_version=NEW.source_version AND p.operation_token=NEW.operation_token AND p.state='VERIFIED'))
 OR (NEW.projection='FINAL' AND (NEW.claim_mode<>'HANDOFF' OR NOT EXISTS(SELECT 1 FROM continuous_final_notice_evidence z WHERE z.spreadsheet_id=NEW.spreadsheet_id AND z.operation_token=NEW.operation_token AND z.epoch_id=NEW.epoch_id AND z.expense_id=NEW.expense_id AND z.source_version=NEW.source_version AND z.operation_kind=NEW.operation_kind)))
 OR (NEW.projection='PUBLICATION' AND ((NEW.claim_mode<>'HANDOFF' AND NOT (NEW.claim_mode='REVIEW' AND NEW.operation_kind='CANCEL' AND EXISTS(SELECT 1 FROM continuous_revoke_review_close_activation WHERE singleton=1))) OR NOT EXISTS(SELECT 1 FROM continuous_publication_intents i JOIN continuous_publication_markers m ON m.spreadsheet_id=i.spreadsheet_id AND m.entity_id=i.entity_id AND m.transition_id=i.transition_id AND m.sheet_id=i.sheet_id AND m.sheet_name=i.sheet_name AND m.row_number=i.row_number AND m.version=i.source_version AND m.marker=i.after_value AND m.state=CASE WHEN i.kind='STAGE' THEN 'STAGED' WHEN i.kind='PUBLISH' THEN 'PUBLISHED' ELSE 'REVOKED' END WHERE i.transition_id=NEW.journal_entity AND i.spreadsheet_id=NEW.spreadsheet_id AND i.entity_id=NEW.expense_id AND i.source_version=NEW.source_version AND i.claim_token=NEW.operation_token AND i.state='VERIFIED' AND (NEW.claim_mode='HANDOFF' OR (NEW.claim_mode='REVIEW' AND i.kind='REVOKE' AND EXISTS(SELECT 1 FROM continuous_publication_review_evidence p WHERE p.transition_id=i.transition_id AND p.source_digest=i.source_digest))) AND ((i.kind IN ('STAGE','PUBLISH') AND NEW.operation_kind='CONFIRM') OR (i.kind='REVOKE' AND NEW.operation_kind='CANCEL'))) OR (SELECT count(*) FROM continuous_publication_intents i WHERE i.spreadsheet_id=NEW.spreadsheet_id AND i.claim_token=NEW.operation_token)<>1))
 OR (SELECT count(*) FROM stable_projection_writes p WHERE p.spreadsheet_id=NEW.spreadsheet_id AND p.operation_token=NEW.operation_token)+(SELECT count(*) FROM stable_expense_cancellation_writes p WHERE p.spreadsheet_id=NEW.spreadsheet_id AND p.operation_token=NEW.operation_token)<>CASE WHEN NEW.projection IN ('FINAL','PUBLICATION') THEN 0 ELSE 1 END
BEGIN SELECT RAISE(ABORT,'review close requires exact verified operation'); END;
